function quizChoice(keys, texts) {
  return texts.map(function (text, i) { return { key: keys[i], text: text }; });
}

function Q(spec) {
  const keys = ["a", "b", "c", "d", "e", "f"];
  const item = {
    id: spec.id,
    subject: spec.subject,
    topic: spec.topic,
    difficulty: spec.difficulty,
    type: spec.type || "single",
    legacy: !!spec.legacy,
    ref: spec.ref || "Lehrplanrichtlinien Bayern, Fachinformatiker, Jgst. 11, Mai 2020",
    q: spec.q,
    explain: spec.explain
  };
  if (spec.worked) item.worked = spec.worked;
  if (spec.guidance) item.guidance = spec.guidance;
  if (spec.type === "short") return item;
  item.choices = {
    de: quizChoice(keys, spec.de),
    en: quizChoice(keys, spec.en),
    fa: quizChoice(keys, spec.fa)
  };
  item.answer = spec.answer;
  return item;
}

